// Regenerates supabase/seed.sql from src/data/seed.ts so the in-memory store and
// the database share one source of starter content. Run: npm run db:seed-sql
import { writeFileSync } from 'node:fs'
import { LANDMARKS, QUESTS } from '../src/data/seed.js'

const q = (value: string | null) => (value === null ? 'null' : `'${value.replaceAll("'", "''")}'`)

const lines = [
  '-- Generated by scripts/generate-seed-sql.ts from src/data/seed.ts. Do not edit by hand.',
  '-- Loaded by `supabase db reset` (see [db.seed] in config.toml).',
  '',
  'insert into public.landmarks (id, name, category, district, latitude, longitude, image_url, admission_fee, rating, visit_count, estimated_visit_minutes, visiting_hours, story) values',
  LANDMARKS.map(
    (l) =>
      `  (${q(l.id)}, ${q(l.name)}, ${q(l.category)}, ${q(l.district)}, ${l.latitude}, ${l.longitude}, ${q(l.imageUrl)}, ${l.admissionFee}, ${l.rating}, ${l.visitCount}, ${l.estimatedVisitMinutes}, ${q(l.visitingHours)}, ${q(JSON.stringify(l.story))}::jsonb)`,
  ).join(',\n') + '\non conflict (id) do nothing;',
  '',
  'insert into public.quests (id, title, description, badge_name) values',
  QUESTS.map((x) => `  (${q(x.id)}, ${q(x.title)}, ${q(x.description)}, ${q(x.badgeName)})`).join(',\n') +
    '\non conflict (id) do nothing;',
  '',
  'insert into public.quest_landmarks (quest_id, landmark_id, position) values',
  QUESTS.flatMap((x) => x.landmarkIds.map((id, i) => `  (${q(x.id)}, ${q(id)}, ${i})`)).join(',\n') +
    '\non conflict do nothing;',
  '',
]

writeFileSync(new URL('../supabase/seed.sql', import.meta.url), lines.join('\n'))
console.log('Wrote supabase/seed.sql')
